#include <iostream>
#include <cstdint>
int main() {
  char c = 'a';
  int i = 10;
  double d = 3.14;
  std::uint16_t shortInt = 5;
  // Implicit conversion: char is promoted to int before the addition
  int sum1 = c + i; 
  // Explicit conversion: shortInt is explicitly converted to int
  int sum2 = static_cast<int>(shortInt) + i; 
  // Implicit conversion, int is promoted to double before the addition
  double sum3 = i + d; 
  std::cout << "sum1: " << sum1 << std::endl; 
  std::cout << "sum2: " << sum2 << std::endl; 
  std::cout << "sum3: " << sum3 << std::endl;
  //Avoid this:  It's unclear and could potentially lead to data loss or unexpected results. 
  //double sum4 = i + c; //Less clear conversion
  return 0;
}
